import pickle
import json
from typing import Any, Dict

class PreferenceCache:
    def __init__(self, max_size: int = 10000):
        self.cache: Dict[str, bytes] = {}
        self.max_size = max_size

    def set(self, user_id: str, preferences: Dict[str, Any]) -> None:
        """Store user preferences with fast serialization."""
        if len(self.cache) >= self.max_size:
            # Simple eviction: remove oldest entry
            self.cache.pop(next(iter(self.cache)))

        # pickle is fastest for complex nested objects
        self.cache[user_id] = pickle.dumps(preferences)

    def get(self, user_id: str) -> Dict[str, Any]:
        """Retrieve and deserialize user preferences."""
        if user_id not in self.cache:
            return None

        # Direct deserialization for speed
        return pickle.loads(self.cache[user_id])

    def batch_load(self, user_ids: list) -> Dict[str, Dict[str, Any]]:
        """Load multiple profiles at once."""
        result = {}
        for uid in user_ids:
            cached = self.cache.get(uid)
            if cached:
                result[uid] = pickle.loads(cached)
        return result
